UPDATE task_scheduled_work SET version = #{row.version}, requested_revision = #{row.requestedRevision},
    due_at = #{row.dueAt}, claim_token = #{row.claimToken}, claim_revision = #{row.claimRevision},
    claim_until = #{row.claimUntil}, next_wake_at = #{row.nextWakeAt}
WHERE tenant_id = #{row.tenantId} AND client_id = #{row.clientId} AND handler = #{row.handler}
  AND business_key = #{row.businessKey} AND target_node = #{row.targetNode}
  AND version = #{expectedVersion}
